import json


def _jobs(snap):
    out = {}
    for k, e in snap.items():
        if not isinstance(k, str) or not k.startswith("rq:job:"):
            continue
        rest = k[len("rq:job:"):]
        if ":" in rest or not rest:
            continue
        if not isinstance(e, dict) or e.get("t") != "hash" or not isinstance(e.get("v"), dict):
            continue
        out[rest] = e["v"]
    return out


def _zmembers(snap, key):
    e = snap.get(key)
    if not isinstance(e, dict) or e.get("t") != "zset" or not isinstance(e.get("v"), list):
        return []
    res = []
    for p in e["v"]:
        try:
            res.append(str(p[0]))
        except Exception:
            pass
    return res


def _list(snap, key):
    e = snap.get(key)
    if not isinstance(e, dict) or e.get("t") != "list" or not isinstance(e.get("v"), list):
        return []
    return [str(x) for x in e["v"]]


def _queue_names(snap):
    names = set()
    for k, e in snap.items():
        if not isinstance(k, str):
            continue
        for pre in ("rq:queue:", "rq:wip:", "rq:finished:", "rq:failed:",
                    "rq:deferred:", "rq:scheduled:", "rq:canceled:"):
            if k.startswith(pre):
                n = k[len(pre):]
                if n.endswith(":intermediate") or ":first_seen:" in n:
                    n = n.split(":")[0]
                if n:
                    names.add(n)
    e = snap.get("rq:queues")
    if isinstance(e, dict) and isinstance(e.get("v"), list):
        for x in e["v"]:
            x = str(x)
            if x.startswith("rq:queue:"):
                names.add(x[len("rq:queue:"):])
    for v in _jobs(snap).values():
        if v.get("origin"):
            names.add(str(v["origin"]))
    return sorted(names)


def _membership(snap):
    """queue -> registry -> sorted job ids"""
    res = {}
    for q in _queue_names(snap):
        res[q] = {
            "queued": _list(snap, "rq:queue:" + q),
            "started": sorted({m.split(":")[0] for m in _zmembers(snap, "rq:wip:" + q)}),
            "finished": sorted(_zmembers(snap, "rq:finished:" + q)),
            "failed": sorted(_zmembers(snap, "rq:failed:" + q)),
            "deferred": sorted(_zmembers(snap, "rq:deferred:" + q)),
            "scheduled": sorted(_zmembers(snap, "rq:scheduled:" + q)),
            "canceled": sorted(_zmembers(snap, "rq:canceled:" + q)),
        }
    return res


