def _int(x):
    try:
        if x in (None, ""):
            return None
        return int(x)
    except Exception:
        return None


def _deps(h):
    try:
        d = h.get("dependency_ids")
        if d:
            return list(json.loads(d))
        if h.get("dependency_id"):
            return [h["dependency_id"]]
    except Exception:
        pass
    return []


def _results(snap, jid):
    e = snap.get("rq:results:" + jid)
    if not isinstance(e, dict) or e.get("t") != "stream" or not isinstance(e.get("v"), list):
        return []
    types = {"1": "successful", "2": "failed", "3": "stopped", "4": "retried"}
    out = []
    for f in e["v"]:
        if isinstance(f, dict):
            out.append(types.get(str(f.get("type")), str(f.get("type"))))
    return out


